package com.dropmarket;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * Drop tables shipped inside the plugin (a snapshot of the OSRS Wiki, regenerated by
 * tools/generate-wiki-drops.mjs before each release), so no network request or opt-in is needed for them.
 */
@Slf4j
@Singleton
class BundledDropTables
{
	private static final String RESOURCE = "wiki-drops.json";

	private final Gson gson;
	private Map<String, List<String>> tables;

	@Inject
	BundledDropTables(Gson gson)
	{
		this.gson = gson;
	}

	/** Rare drops for the monster ordered by wiki drop value, or null if the snapshot doesn't have it. */
	synchronized List<String> lookup(String source)
	{
		if (tables == null)
		{
			tables = load();
		}
		List<String> table = tables.get(DropTables.normalize(source));
		return table == null ? null : Collections.unmodifiableList(table);
	}

	private Map<String, List<String>> load()
	{
		try (InputStream in = BundledDropTables.class.getResourceAsStream(RESOURCE))
		{
			if (in == null)
			{
				log.warn("Bundled drop tables missing");
				return Collections.emptyMap();
			}
			Map<String, List<String>> parsed = gson.fromJson(
				new InputStreamReader(in, StandardCharsets.UTF_8),
				new TypeToken<Map<String, List<String>>>() { }.getType());
			return parsed == null ? Collections.emptyMap() : parsed;
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Bundled drop tables unreadable", e);
			return Collections.emptyMap();
		}
	}
}

package com.dropmarket;

/** When a win's celebration (the flash, the "RESOLVED" state) ends. */
final class Celebration
{
	private Celebration()
	{
	}

	/**
	 * Over once its time is up, or as soon as you move to a different source. Staying on the same monster does NOT keep
	 * it going: killing the same boss over and over used to leave the celebration flashing indefinitely.
	 */
	static boolean isOver(int ticksSinceWin, int celebrationTicks, boolean differentSource)
	{
		return differentSource || ticksSinceWin >= celebrationTicks;
	}
}

package com.dropmarket;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.callback.ClientThread;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/** Which collection log slots exist and which this account has unlocked, stored as normalized item names. */
@Slf4j
@Singleton
class CollectionLogTracker
{
	private static final String KEY_KNOWN = "clogKnown";
	private static final String KEY_OBTAINED = "clogObtained";
	private static final String KEY_FULL = "clogFull";
	private static final HttpUrl RUNEPROFILE = HttpUrl.get("https://api.runeprofile.com/v1/accounts");

	private final ProfileStore store;
	private final OkHttpClient http;
	private final Gson gson;
	private final ClientThread clientThread;

	private final Set<String> known = new HashSet<>();
	private final Set<String> obtained = new HashSet<>();
	private boolean fullLog;

	@Inject
	CollectionLogTracker(ProfileStore store, OkHttpClient http, Gson gson, ClientThread clientThread)
	{
		this.store = store;
		this.http = http;
		this.gson = gson;
		this.clientThread = clientThread;
	}

	void load()
	{
		known.clear();
		obtained.clear();
		fullLog = false;
		read(KEY_KNOWN, known);
		read(KEY_OBTAINED, obtained);
		fullLog = "true".equals(store.get(KEY_FULL));
	}

	private void read(String key, Set<String> into)
	{
		String value = store.get(key);
		if (value != null && !value.isEmpty())
		{
			into.addAll(Arrays.asList(value.split(",")));
		}
	}

	private void save()
	{
		store.set(KEY_KNOWN, String.join(",", known));
		store.set(KEY_OBTAINED, String.join(",", obtained));
	}

	/** True once the whole log is known (from RuneProfile), so slot membership is authoritative. */
	boolean hasFullLog()
	{
		return fullLog;
	}

	boolean isSlot(String item)
	{
		return known.contains(DropTables.normalize(item));
	}

	boolean isObtained(String item)
	{
		return obtained.contains(DropTables.normalize(item));
	}

	/** Returns true if anything changed. Call {@link #flush()} after a batch. */
	boolean record(String item, boolean got)
	{
		String n = DropTables.normalize(item);
		if (n.isEmpty())
		{
			return false;
		}
		boolean changed = known.add(n);
		if (got)
		{
			changed |= obtained.add(n);
		}
		return changed;
	}

	void recordAndFlush(String item, boolean got)
	{
		if (record(item, got))
		{
			save();
		}
	}

	void flush()
	{
		save();
	}

	void fetchRuneProfile(String username, Runnable onClientThread)
	{
		HttpUrl url = RUNEPROFILE.newBuilder()
			.addPathSegment(username.replace(' ', ' '))
			.addPathSegment("collection-log")
			.build();

		http.newCall(new Request.Builder().url(url).build()).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("RuneProfile lookup failed", e);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (ResponseBody body = response.body())
				{
					if (!response.isSuccessful() || body == null)
					{
						log.debug("RuneProfile returned {}", response.code());
						return;
					}
					JsonObject clog = gson.fromJson(body.string(), JsonObject.class);
					clientThread.invoke(() ->
					{
						try
						{
							applyRuneProfile(clog);
							onClientThread.run();
						}
						catch (Exception | LinkageError e)
						{
							log.debug("RuneProfile result failed", e);
						}
					});
				}
				catch (Exception e)
				{
					log.debug("RuneProfile parse failed", e);
				}
			}
		});
	}

	private void applyRuneProfile(JsonObject clog)
	{
		Map<String, Boolean> slots = parseRuneProfile(clog);
		if (slots.isEmpty())
		{
			return;
		}
		slots.forEach(this::record);
		fullLog = true;
		store.set(KEY_FULL, "true");
		save();
	}

	/** Item name -> obtained, from RuneProfile's tabs[].pages[].items[] (quantity 0 = locked). */
	static Map<String, Boolean> parseRuneProfile(JsonObject clog)
	{
		Map<String, Boolean> slots = new HashMap<>();
		JsonArray tabs = clog.getAsJsonArray("tabs");
		if (tabs == null)
		{
			return slots;
		}
		for (JsonElement tab : tabs)
		{
			for (JsonElement page : tab.getAsJsonObject().getAsJsonArray("pages"))
			{
				for (JsonElement el : page.getAsJsonObject().getAsJsonArray("items"))
				{
					JsonObject item = el.getAsJsonObject();
					JsonElement qty = item.get("quantity");
					slots.merge(item.get("name").getAsString(), qty != null && qty.getAsInt() > 0, Boolean::logicalOr);
				}
			}
		}
		return slots;
	}
}

package com.dropmarket;

import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.audio.AudioPlayer;
import net.runelite.client.util.Filepath;

/**
 * Plays the player's own sound files on a win. The files live in the plugin's own data folder (the Filepath RuneLite
 * hands the plugin, which can't reach anywhere else) as plain WAVs under fixed names, one per kind of win with win.wav
 * as the fallback for all of them. They are played with RuneLite's AudioPlayer on RuneLite's executor, never the client
 * thread. Nothing is bundled, downloaded or deleted, and the plugin never opens the folder for the player: the how-to
 * and a chat message give them its path.
 */
@Slf4j
@Singleton
class CustomSound
{
	static final String FILE_NAME = SoundEvent.WIN.fileName();
	static final String README_NAME = "HOW-TO.txt";
	// A win sound is a second or two; this stops a huge file being played by mistake.
	private static final long MAX_BYTES = 8L * 1024 * 1024;

	private static final String README_TITLE = "Prediction Market Drops - custom win sounds";

	private static final String README = String.join(System.lineSeparator(),
		README_TITLE,
		"",
		"1. Find or make a short sound as a WAV file (.wav). MP3 and OGG files won't work, and renaming one doesn't",
		"   change what it is: convert it, for example in Audacity with File > Export > Export as WAV.",
		"2. Name it exactly " + SoundEvent.WIN.fileName() + " and put it in this folder (replace the file if one is there).",
		"3. In the plugin settings choose Win Sound > Custom file, then tick Test Win Sound to hear it.",
		"",
		"Different sounds for different wins (all optional, anything missing just uses " + SoundEvent.WIN.fileName() + "):",
		"  " + SoundEvent.COLLECTION_LOG.fileName() + "   a new collection log item",
		"  " + SoundEvent.PET.fileName() + "   a pet drop",
		"",
		"Tips: keep sounds short. The Win Sound Volume setting can only turn a file down, so make it as loud as you",
		"want it. Changes are picked up the next time a sound plays. To go back to the built-in sound, choose another",
		"Win Sound. If a file is missing or can't be read, the Grand Exchange chime plays instead.",
		"Nothing in this folder is ever deleted, and folders inside it are ignored, so you can keep spare sounds there.",
		"");

	private final ScheduledExecutorService executor;
	private final AudioPlayer audioPlayer;
	// The plugin's data folder, handed over by the plugin when it starts; null until then (or if RuneLite couldn't make it).
	private volatile Filepath folder;

	@Inject
	CustomSound(ScheduledExecutorService executor, AudioPlayer audioPlayer)
	{
		this.executor = executor;
		this.audioPlayer = audioPlayer;
	}

	void setFolder(Filepath folder)
	{
		this.folder = folder;
	}

	/** Where the sound files go, for showing to the player; empty if the folder isn't available. */
	String folderPath()
	{
		Filepath current = folder;
		return current == null ? "" : current.toString();
	}

	/** win.wav, the sound every win falls back to; null if there is no folder. */
	Filepath file()
	{
		Filepath current = folder;
		return current == null ? null : current.joinSegment(FILE_NAME);
	}

	/** The file for this kind of win if the player made one, else win.wav (which may not exist); null with no folder. */
	Filepath fileFor(SoundEvent event)
	{
		Filepath current = folder;
		if (current == null)
		{
			return null;
		}
		if (event != null && event != SoundEvent.WIN)
		{
			Filepath specific = current.joinSegment(event.fileName());
			if (specific.isFile())
			{
				return specific;
			}
		}
		return current.joinSegment(FILE_NAME);
	}

	/** Makes sure the folder is there with the how-to in it, so the player has somewhere obvious to drop the files. */
	void prepareFolder()
	{
		Filepath current = folder;
		if (current == null)
		{
			return;
		}
		try
		{
			current.createDirectories();
			Filepath readme = current.joinSegment(README_NAME);
			boolean write = !readme.exists();
			if (!write)
			{
				// An older copy of our own how-to is refreshed; one the player has edited or replaced is left alone.
				try (InputStream in = readme.openInputStream())
				{
					String existing = new String(in.readAllBytes(), StandardCharsets.UTF_8);
					write = existing.startsWith(README_TITLE) && !existing.equals(README);
				}
			}
			if (write)
			{
				readme.write(README);
			}
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("Could not prepare the sound folder", e);
		}
	}

	/** Decibels of gain for a 0-100 volume: 100 is the file as it is, lower is quieter, 0 is silent. */
	static float gainDb(int percent)
	{
		int clamped = Math.max(0, Math.min(100, percent));
		return clamped == 0 ? -80f : (float) (20 * Math.log10(clamped / 100.0));
	}

	/**
	 * Plays the sound for this kind of win in the background. If there is no usable file (missing, too big, not a WAV,
	 * no audio device) onFailure runs, on the background thread, so the caller can fall back to a built-in sound.
	 */
	void play(SoundEvent event, int percent, Runnable onFailure)
	{
		if (percent <= 0)
		{
			return;
		}
		try
		{
			executor.submit(() -> playNow(fileFor(event), percent, onFailure));
		}
		catch (RuntimeException e)
		{
			log.debug("Could not start the custom sound", e);
			fail(onFailure);
		}
	}

	private void playNow(Filepath file, int percent, Runnable onFailure)
	{
		try
		{
			if (file == null || !file.isFile() || file.size() > MAX_BYTES)
			{
				fail(onFailure);
				return;
			}
			audioPlayer.play(file, gainDb(percent));
		}
		catch (Exception | LinkageError e)
		{
			// Includes the unsupported-format and no-audio-device errors the player reports.
			log.debug("Custom win sound failed", e);
			fail(onFailure);
		}
	}

	private void fail(Runnable onFailure)
	{
		try
		{
			onFailure.run();
		}
		catch (Exception | LinkageError e)
		{
			log.debug("Custom sound fallback failed", e);
		}
	}
}

package com.dropmarket;

import java.util.Random;

/**
 * How a market's odds tend to wander. STEADY is the everyday movement; the rest are rarer flavors. The numbers are
 * the anchor range the line is pulled toward, the noise, occasional jumps, and a soft ceiling (CLIMBER may go higher).
 */
enum DriftProfile
{
	// label, weight, anchor min, anchor span, noise, jump chance, jump min, jump span, anchor re-roll chance, ceiling
	STEADY("Steady", 55, 6, 56, 2.6, 0.07, 6, 10, 0.03, 72),
	// Creeps upward toward ~85-90 as the raid or boss fight nears its end, then falls back.
	CLIMBER("Climber", 15, 8, 20, 2.4, 0.04, 5, 8, 0.0, 91),
	CHOPPY("Choppy", 10, 12, 43, 4.2, 0.14, 8, 10, 0.06, 82),
	// Quiet and low-ish, barely moves.
	SLEEPER("Sleeper", 8, 10, 20, 1.2, 0.02, 4, 6, 0.01, 70),
	// Sits low, then now and then pops up for a few steps before settling back.
	SPIKE("Spike", 7, 10, 15, 2.0, 0.0, 0, 0, 0.0, 82),
	// Starts high and bleeds away.
	FADER("Fader", 5, 45, 20, 2.4, 0.04, 5, 8, 0.0, 82);

	final String label;
	final int weight;
	final double anchorMin;
	final double anchorSpan;
	final double noise;
	final double jumpChance;
	final double jumpMin;
	final double jumpSpan;
	final double rerollChance;
	final double ceiling;

	DriftProfile(String label, int weight, double anchorMin, double anchorSpan, double noise, double jumpChance,
		double jumpMin, double jumpSpan, double rerollChance, double ceiling)
	{
		this.label = label;
		this.weight = weight;
		this.anchorMin = anchorMin;
		this.anchorSpan = anchorSpan;
		this.noise = noise;
		this.jumpChance = jumpChance;
		this.jumpMin = jumpMin;
		this.jumpSpan = jumpSpan;
		this.rerollChance = rerollChance;
		this.ceiling = ceiling;
	}

	double rollAnchor(Random random)
	{
		return anchorMin + random.nextDouble() * anchorSpan;
	}

	/** A random profile by weight: STEADY most of the time, CLIMBER uncommon, the rest occasionally. */
	static DriftProfile roll(Random random)
	{
		int total = 0;
		for (DriftProfile p : values())
		{
			total += p.weight;
		}
		int pick = random.nextInt(total);
		for (DriftProfile p : values())
		{
			pick -= p.weight;
			if (pick < 0)
			{
				return p;
			}
		}
		return STEADY;
	}
}

package com.dropmarket;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

// Keep every keyName stable: it is what a player's saved settings are stored under.
@ConfigGroup(DropMarketConfig.GROUP)
public interface DropMarketConfig extends Config
{
	String GROUP = "dropmarket";
	Color DEFAULT_LINE_COLOR = new Color(0x00D991);
	Color DEFAULT_LINE2_COLOR = new Color(0x3D7BFF);
	Color DEFAULT_BAR1_COLOR = new Color(0x00D991);
	Color DEFAULT_BAR2_COLOR = new Color(0x1652F0);
	// Classic stock-ticker red for a negative move.
	Color DEFAULT_NEGATIVE_DELTA_COLOR = new Color(0xE5484D);

	// Sections run top to bottom in order of importance.
	String SECTION_DATA = "dataSources";
	String SECTION_DISPLAY = "display";
	String SECTION_DROPS = "dropLists";
	String SECTION_WINS = "winRules";
	String SECTION_CELEBRATION = "celebration";
	String SECTION_LINE1 = "graphLine1";
	String SECTION_LINE2 = "graphLine2";
	String SECTION_BAR1 = "headerBar1";
	String SECTION_BAR2 = "headerBar2";

	// ---- Data sources (opt-in, third party) ---------------------------------------------------------------------

	@ConfigSection(
		name = "Data Sources",
		description = "Optional lookups that contact third-party servers",
		position = 1,
		closedByDefault = true
	)
	String dataSourcesSection = SECTION_DATA;

	@ConfigItem(
		keyName = "runeProfileSync",
		name = "RuneProfile Collection Log",
		description = "Read your collection log from RuneProfile (requires the RuneProfile plugin to have synced it).<br>"
			+ "Without this, unlocks are learned by browsing your collection log in-game.",
		warning = "This feature submits your IP address to a 3rd-party server not controlled or verified by RuneLite developers",
		section = SECTION_DATA,
		position = 1
	)
	default boolean runeProfileSync()
	{
		return false;
	}

	@ConfigItem(
		keyName = "wikiLookup",
		name = "OSRS Wiki Drop Tables",
		description = "Live-look up drop tables on the OSRS Wiki for monsters missing from the tables bundled in the plugin<br>"
			+ "(most monsters are bundled and need no lookup)",
		warning = "This feature submits your IP address to a 3rd-party server not controlled or verified by RuneLite developers",
		section = SECTION_DATA,
		position = 2
	)
	default boolean wikiLookup()
	{
		return false;
	}

	// ---- Display ----------------------------------------------------------------------------------------------

	@ConfigSection(
		name = "Display",
		description = "How big the overlay is",
		position = 2,
		closedByDefault = true
	)
	String displaySection = SECTION_DISPLAY;

	@ConfigItem(
		keyName = "overlayLayout",
		name = "Overlay Layout",
		description = "Full: the whole card with chart, volume and axis.<br>"
			+ "Compact: a short card with the title, odds and a sparkline.<br>"
			+ "Ticker: a single line, like a stock ticker (scrolls long titles; header bars are hidden).",
		section = SECTION_DISPLAY,
		position = 1
	)
	default OverlayLayout overlayLayout()
	{
		return OverlayLayout.FULL;
	}

	// ---- Drop lists ---------------------------------------------------------------------------------------------

	@ConfigSection(
		name = "Drop Lists",
		description = "Drops to always bet on, and drops to never count",
		position = 3,
		closedByDefault = true
	)
	String dropListsSection = SECTION_DROPS;

	@ConfigItem(
		keyName = "priorityItems",
		name = "Priority Drops",
		description = "One per line as 'Source: Item' to bet on that item instead of the most expensive drop.<br>"
			+ "A priority drop always counts as a win when you get it, whatever it's worth.<br>"
			+ "e.g. 'Chambers of Xeric: Dexterous prayer scroll' or 'Zulrah: Serpentine visage'.<br>"
			+ "Raids also accept CoX / ToB / ToA. Multiple lines for the same source are rolled between evenly.",
		section = SECTION_DROPS,
		position = 1
	)
	default String priorityDrops()
	{
		return "";
	}

	@ConfigItem(
		keyName = "blacklistItems",
		name = "Blacklisted Drops",
		description = "One per line as 'Source: Item' to never bet on or celebrate that item.<br>"
			+ "e.g. 'Zulrah: Tanzanite fang' or 'CoX: Dexterous prayer scroll'.<br>"
			+ "Raids also accept CoX / ToB / ToA. Trumps everything, including priority drops and Resolve Win on Every Drop.",
		section = SECTION_DROPS,
		position = 2
	)
	default String blacklistedDrops()
	{
		return "";
	}

	// ---- Market value -------------------------------------------------------------------------------------------

	@ConfigSection(
		name = "Market Value",
		description = "Which monsters get a market, and what a drop is worth to count as a win",
		position = 4,
		closedByDefault = true
	)
	String winRulesSection = SECTION_WINS;

	@ConfigItem(
		keyName = "valueUnit",
		name = "Value Units",
		description = "The denomination the two values below are entered in (k = thousands, m = millions, b = billions)",
		section = SECTION_WINS,
		position = 1
	)
	default ValueUnit valueUnit()
	{
		return ValueUnit.K;
	}

	@ConfigItem(
		keyName = "marketMinimumAmount",
		name = "Market Minimum Drop Value",
		description = "Which monsters get a market (what the market bets on), in the units chosen above: if a monster's<br>"
			+ "best tradeable drop is worth less than this it shows LIVE ODDS, unless it drops a collection log item<br>"
			+ "you haven't unlocked. Not the same as Win Minimum Drop Value, which decides what counts as a win.",
		section = SECTION_WINS,
		position = 2
	)
	@Range(min = 0, max = 100_000)
	default int marketMinimumAmount()
	{
		return 250;
	}

	@ConfigItem(
		keyName = "winMinimumAmount",
		name = "Win Minimum Drop Value",
		description = "Minimum value for a success hit on the odds (what counts as a win, once a market is showing), in<br>"
			+ "the units chosen above: a drop worth less than this won't resolve the market or flash.<br>"
			+ "A collection log item new to your account, or one with no GE price, still counts.<br>"
			+ "Not the same as Market Minimum Drop Value, which decides what the market bets on.",
		section = SECTION_WINS,
		position = 3
	)
	@Range(min = 0, max = 100_000)
	default int winMinimumAmount()
	{
		return 2_000;
	}

	// ---- Celebration --------------------------------------------------------------------------------------------

	@ConfigSection(
		name = "Celebration",
		description = "What counts as a win, and how a win looks and how long it lasts",
		position = 5,
		closedByDefault = true
	)
	String celebrationSection = SECTION_CELEBRATION;

	@ConfigItem(
		keyName = "popOffOnEveryDrop",
		name = "Resolve Win on Every Drop",
		description = "Treat every drop you receive as a win, ignoring Win Minimum Drop Value.<br>"
			+ "Blacklisted drops still never count, and priority drops always do.",
		section = SECTION_CELEBRATION,
		position = 1
	)
	default boolean resolveWinOnEveryDrop()
	{
		return false;
	}

	@ConfigItem(
		keyName = "flashOnDrop",
		name = "Flash Purple on Win",
		description = "Flash the overlay purple when a drop hits (both lines too, when the second line is shown)",
		section = SECTION_CELEBRATION,
		position = 2
	)
	default boolean flashOnWin()
	{
