import com.google.gson.Gson;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * Whether an item is a collection log drop of a monster/activity (so Hydra bones don't count, a Tanzanite fang does).
 * Backed by the bundled wiki snapshot, plus the hand-written tables, whose items are log chases by construction. How
 * common the item is isn't judged here: the plugin price-checks log drops unless they're new to the account.
 */
@Slf4j
@Singleton
class UniqueDrops
{
	private static final String RESOURCE = "collection-log.json";

	private static final class Data
	{
		List<String> items;
		Map<String, List<String>> sources;
	}

	private final Gson gson;
	private Set<String> logItems;
	private Map<String, Set<String>> logDropsBySource;

	@Inject
	UniqueDrops(Gson gson)
	{
		this.gson = gson;
	}

	synchronized boolean isLogDrop(String source, String item)
	{
		if (source == null || item == null)
		{
			return false;
		}
		load();
		String n = DropTables.normalize(item);
		Set<String> fromWiki = logDropsBySource.get(DropTables.normalize(source));
		if (fromWiki != null && fromWiki.contains(n))
		{
			return true;
		}
		// Hand-written tables list only the notable chases; they count when they're log items (or pets).
		List<String> curated = DropTables.lookup(source);
		return curated != null && (logItems.contains(n) || DropTables.isPet(item)) && contains(curated, n);
	}

	private static boolean contains(List<String> table, String normalizedItem)
	{
		for (String entry : table)
		{
			if (DropTables.normalize(entry).equals(normalizedItem))
			{
				return true;
			}
		}
		return false;
	}

	private void load()
	{
		if (logItems != null)
		{
			return;
		}
		logItems = new HashSet<>();
		logDropsBySource = new HashMap<>();
		try (InputStream in = UniqueDrops.class.getResourceAsStream(RESOURCE))
		{
			if (in == null)
			{
				log.warn("Bundled collection log data missing");
				return;
			}
			Data data = gson.fromJson(new InputStreamReader(in, StandardCharsets.UTF_8), Data.class);
			if (data == null)
			{
				return;
			}
			for (String item : data.items == null ? Collections.<String>emptyList() : data.items)
			{
				logItems.add(DropTables.normalize(item));
			}
			if (data.sources != null)
			{
				data.sources.forEach((source, items) ->
				{
					Set<String> set = new HashSet<>();
					items.forEach(item -> set.add(DropTables.normalize(item)));
					logDropsBySource.put(source, set);
				});
			}
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Bundled collection log data unreadable", e);
		}
	}
}

package com.dropmarket;

import com.google.gson.Gson;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * Untradeable drops that end up, through any number of crafting steps, in an expensive tradeable item (a vestige
 * becomes an icon becomes a ring), from the bundled snapshot made by tools/generate-wiki-drops.mjs. They have no GE
 * price of their own, so each one is worth the price of the item it ends up in. Parts of items that need several
 * parts (the Soulreaper axe) are listed with a value of 0: still worth celebrating, but not worth the whole item.
 */
@Slf4j
@Singleton
class ValuableComponents
{
	private static final String RESOURCE = "valuable-components.json";

	private static final class Entry
	{
		String name;
		long value;
		List<String> sources;
		List<String> parts;
	}

	private final Gson gson;
	private Map<String, Entry> byName;
	private Map<String, List<String>> namesBySource;

	@Inject
	ValuableComponents(Gson gson)
	{
		this.gson = gson;
	}

	synchronized boolean contains(String item)
	{
		load();
		return item != null && byName.containsKey(DropTables.normalize(item));
	}

	/** What the item is worth through what it becomes, or 0 if it has no assigned value (or isn't on the list). */
	synchronized long valueOf(String item)
	{
		load();
		Entry entry = item == null ? null : byName.get(DropTables.normalize(item));
		return entry == null ? 0 : entry.value;
	}

	/** The other untradeable drops needed for the same finished item (a Noxious blade's siblings), or empty. */
	synchronized List<String> partsOf(String item)
	{
		load();
		Entry entry = item == null ? null : byName.get(DropTables.normalize(item));
		return entry == null || entry.parts == null ? Collections.emptyList() : entry.parts;
	}

	/** The listed items that drop from this source, e.g. the Ultor vestige for Vardorvis. */
	synchronized List<String> dropsFrom(String source)
	{
		load();
		List<String> names = source == null ? null : namesBySource.get(DropTables.normalize(source));
		return names == null ? Collections.emptyList() : names;
	}

	private void load()
	{
		if (byName != null)
		{
			return;
		}
		byName = new HashMap<>();
		namesBySource = new HashMap<>();
		try (InputStream in = ValuableComponents.class.getResourceAsStream(RESOURCE))
		{
			if (in == null)
			{
				log.warn("Bundled valuable components missing");
				return;
			}
			Entry[] entries = gson.fromJson(new InputStreamReader(in, StandardCharsets.UTF_8), Entry[].class);
			for (Entry entry : entries == null ? new Entry[0] : entries)
			{
				byName.put(DropTables.normalize(entry.name), entry);
				for (String source : entry.sources == null ? Collections.<String>emptyList() : entry.sources)
				{
					namesBySource.computeIfAbsent(source, k -> new ArrayList<>()).add(entry.name);
				}
			}
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Bundled valuable components unreadable", e);
		}
	}
}

